import 'package:flutter/material.dart';
void main()=>runApp(const Demo());
const green=Color(0xff087d5c);
class Demo extends StatelessWidget{const Demo({super.key});@override Widget build(BuildContext context)=>MaterialApp(debugShowCheckedModeBanner:false,theme:ThemeData(colorScheme:ColorScheme.fromSeed(seedColor:green),useMaterial3:true),home:const Home());}
class Home extends StatefulWidget{const Home({super.key});@override State<Home> createState()=>_HomeState();}
class _HomeState extends State<Home>{int tab=0;final pages=['الرئيسية','الرسائل','المتجر','ملفي'];@override Widget build(BuildContext context)=>Directionality(textDirection:TextDirection.rtl,child:Scaffold(appBar:AppBar(backgroundColor:green,foregroundColor:Colors.white,title:Text('TotiChat  •  ${pages[tab]}')),body:tab==0?ListView(children:[Container(height:135,margin:const EdgeInsets.all(14),decoration:BoxDecoration(gradient:const LinearGradient(colors:[green,Color(0xff16b38a)]),borderRadius:BorderRadius.circular(20)),child:const Center(child:Text('TotiChat\nغرف صوتية ومجتمعات',textAlign:TextAlign.center,style:TextStyle(color:Colors.white,fontSize:25,fontWeight:FontWeight.bold)))),for(var i=1;i<=12;i++)Card(margin:const EdgeInsets.symmetric(horizontal:14,vertical:5),child:ListTile(leading:CircleAvatar(backgroundColor:green,child:Text('$i',style:const TextStyle(color:Colors.white))),title:Text('غرفة الدردشة $i'),subtitle:const Text('انضم إلى الغرفة الصوتية'),trailing:const Icon(Icons.chevron_left),onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>Room(number:i))))]):Center(child:Column(mainAxisSize:MainAxisSize.min,children:[Icon([Icons.home,Icons.chat,Icons.store,Icons.person][tab],size:70,color:green),const SizedBox(height:20),Text(pages[tab],style:const TextStyle(fontSize:28)),const Text('واجهة تجريبية بدون خادم')])),bottomNavigationBar:NavigationBar(selectedIndex:tab,onDestinationSelected:(i)=>setState(()=>tab=i),destinations:const [NavigationDestination(icon:Icon(Icons.home),label:'الرئيسية'),NavigationDestination(icon:Icon(Icons.chat),label:'الرسائل'),NavigationDestination(icon:Icon(Icons.store),label:'المتجر'),NavigationDestination(icon:Icon(Icons.person),label:'ملفي')])));}
}
class Room extends StatefulWidget{final int number;const Room({super.key,required this.number});@override State<Room> createState()=>_RoomState();}
class _RoomState extends State<Room>{final controller=TextEditingController();final messages=<String>['أهلاً بكم في الغرفة'];@override Widget build(BuildContext context)=>Directionality(textDirection:TextDirection.rtl,child:Scaffold(backgroundColor:const Color(0xff102a27),appBar:AppBar(backgroundColor:green,foregroundColor:Colors.white,title:Text('غرفة ${widget.number}')),body:Column(children:[const SizedBox(height:14),const Text('مرحباً بكم في TotiChat',style:TextStyle(color:Colors.amber,fontSize:20)),Expanded(flex:3,child:GridView.builder(padding:const EdgeInsets.all(12),gridDelegate:const SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount:5,childAspectRatio:.75),itemCount:15,itemBuilder:(c,i)=>Column(children:[CircleAvatar(radius:24,backgroundColor:const Color(0xff286e5b),child:Icon(i==0?Icons.mic:Icons.event_seat,color:Colors.white)),const SizedBox(height:4),Text('مقعد ${i+1}',style:const TextStyle(color:Colors.white,fontSize:11))]))),Expanded(child:ListView(children:messages.map((m)=>Padding(padding:const EdgeInsets.all(5),child:Text(m,style:const TextStyle(color:Colors.white)))).toList())),Row(children:[IconButton(onPressed:()=>showModalBottomSheet(context:context,builder:(_)=>SafeArea(child:Column(mainAxisSize:MainAxisSize.min,children:[const Text('الهدايا - معاينة فقط'),for(final name in ['وردة','قلب','تاج'])ListTile(title:Text(name),onTap:()=>Navigator.pop(context))]))),icon:const Icon(Icons.card_giftcard,color:Colors.amber)),Expanded(child:TextField(controller:controller,style:const TextStyle(color:Colors.white),decoration:const InputDecoration(hintText:'اكتب رسالة',hintStyle:TextStyle(color:Colors.white54)))),IconButton(onPressed:(){if(controller.text.trim().isNotEmpty)setState((){messages.add(controller.text.trim());controller.clear();});},icon:const Icon(Icons.send,color:Colors.white))])])));}
}
